class Point {
    int x;

    Point(int x) {
        this.x = x;
    }

    Point(Point p) {
        this.x = p.x;
    }
}

public class Main {
    public static void main(String[] args) {
        Point p1 = new Point(4);
        Point p2 = new Point(p1);
        p2.x = 99;
        System.out.println(p1.x);
        System.out.println(p2.x);
    }
}

